using System;
using System.Text.RegularExpressions;
using System.Web;

namespace InformationWeb.Utility
{
    public static class HtmlContentHelper
    {
        private const string GoogleDocsViewerFormat = "https://docs.google.com/gview?url={0}&embedded=true";
        private const string WpUploadsPrefix = "/wp-content/uploads/";

        private static readonly Regex IframeTagRegex = new Regex(
            @"<iframe\b[^>]*>",
            RegexOptions.IgnoreCase | RegexOptions.Compiled
        );

        private static readonly Regex IframeSrcRegex = new Regex(
            @"\bsrc\s*=\s*(?:""([^""]*)""|'([^']*)'|([^\s>]+))",
            RegexOptions.IgnoreCase | RegexOptions.Compiled
        );

        public static string ProcessPdfIframeContent(string htmlContent, HttpRequest request)
        {
            string siteBaseUrl = GetSiteBaseUrl(request);
            return ProcessPdfIframeContent(htmlContent, siteBaseUrl);
        }

        public static string ProcessPdfIframeContent(string htmlContent, string siteBaseUrl)
        {
            if (string.IsNullOrEmpty(htmlContent))
            {
                return string.Empty;
            }

            return IframeTagRegex.Replace(htmlContent, delegate(Match match)
            {
                return ReplacePdfIframeSrc(match.Value, siteBaseUrl);
            });
        }

        private static string ReplacePdfIframeSrc(string iframeTag, string siteBaseUrl)
        {
            Match srcMatch = IframeSrcRegex.Match(iframeTag);
            if (!srcMatch.Success)
            {
                return iframeTag;
            }

            string src = GetSrcValue(srcMatch);
            if (!IsPdfUrl(src))
            {
                return iframeTag;
            }

            string absolutePdfUrl = ToAbsolutePdfUrl(src, siteBaseUrl);
            string googleViewerUrl = String.Format(
                GoogleDocsViewerFormat,
                HttpUtility.UrlEncode(absolutePdfUrl)
            );

            return IframeSrcRegex.Replace(
                iframeTag,
                String.Format("src=\"{0}\"", googleViewerUrl)
            );
        }

        private static string GetSrcValue(Match srcMatch)
        {
            if (srcMatch.Groups[1].Success)
            {
                return srcMatch.Groups[1].Value;
            }

            if (srcMatch.Groups[2].Success)
            {
                return srcMatch.Groups[2].Value;
            }

            return srcMatch.Groups[3].Value;
        }

        private static bool IsPdfUrl(string url)
        {
            if (string.IsNullOrEmpty(url))
            {
                return false;
            }

            string path = url;
            int queryIndex = path.IndexOf('?');
            if (queryIndex >= 0)
            {
                path = path.Substring(0, queryIndex);
            }

            int hashIndex = path.IndexOf('#');
            if (hashIndex >= 0)
            {
                path = path.Substring(0, hashIndex);
            }

            return path.EndsWith(".pdf", StringComparison.OrdinalIgnoreCase);
        }

        private static string ToAbsolutePdfUrl(string src, string siteBaseUrl)
        {
            if (string.IsNullOrEmpty(src))
            {
                return src;
            }

            if (src.StartsWith("http://", StringComparison.OrdinalIgnoreCase) ||
                src.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
            {
                return src;
            }

            if (src.StartsWith(WpUploadsPrefix, StringComparison.OrdinalIgnoreCase))
            {
                if (!string.IsNullOrEmpty(siteBaseUrl))
                {
                    return siteBaseUrl.TrimEnd('/') + src;
                }
            }

            return src;
        }

        private static string GetSiteBaseUrl(HttpRequest request)
        {
            if (request == null || request.Url == null)
            {
                return string.Empty;
            }

            return request.Url.Scheme + "://" + request.Url.Authority;
        }
    }
}

